#!/usr/bin/env python3
"""
P02S: Parser-based TOML/JSON/YAML codemod for structured reference and identity changes.

This module implements format-specific parsers and transformations for TOML, JSON,
and YAML files, preserving comments, formatting, ordering, and other syntax
characteristics to the degree supported by each format's parser.
"""

import argparse
import importlib.metadata
import json
import sys
from dataclasses import dataclass, field
from enum import Enum
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple, Union

try:
    import tomli
    import tomli_w
except ImportError:
    tomli = None
    tomli_w = None

try:
    import yaml
except ImportError:
    yaml = None


# ============================================================================
# Version pinning: assert exact parser versions
# ============================================================================

def _assert_parser_versions():
    """Assert exact parser versions to fail closed on unexpected environments."""
    required_versions = {
        "PyYAML": "6.0.3",
    }
    for package, required_version in required_versions.items():
        try:
            actual = importlib.metadata.version(package)
            if actual != required_version:
                raise RuntimeError(
                    f"Parser version mismatch: {package} is {actual}, "
                    f"expected {required_version}. This codemod is not "
                    f"portable across parser versions."
                )
        except importlib.metadata.PackageNotFoundError:
            raise RuntimeError(
                f"Required parser not found: {package} {required_version}. "
                f"Install via: pip install {package}=={required_version}"
            )


_assert_parser_versions()


# ============================================================================
# Diagnostic and result types
# ============================================================================

class DiagnosticKind(str, Enum):
    """Kinds of diagnostics emitted during transformation."""

    # Transformation events (not errors)
    TOML_KEY_REWRITTEN = "toml_key_rewritten"
    JSON_KEY_REWRITTEN = "json_key_rewritten"
    YAML_KEY_REWRITTEN = "yaml_key_rewritten"

    # Warnings and errors
    UNSAFE_TOML_CONSTRUCT = "unsafe_toml_construct"
    UNSAFE_JSON_CONSTRUCT = "unsafe_json_construct"
    UNSAFE_YAML_CONSTRUCT = "unsafe_yaml_construct"
    PARSE_ERROR = "parse_error"
    UNEXPECTED_REFERENCE = "unexpected_reference"
    RESIDUAL_OLD_REFERENCE = "residual_old_reference"


class DiagnosticSeverity(str, Enum):
    """Severity levels for diagnostics."""
    INFO = "info"
    WARNING = "warning"
    ERROR = "error"


@dataclass
class Diagnostic:
    """A single diagnostic message from transformation."""

    kind: DiagnosticKind
    severity: DiagnosticSeverity
    message: str
    file_path: Optional[str] = None
    line_number: Optional[int] = None
    context: Optional[str] = None


@dataclass
class TransformationResult:
    """Result of a single file transformation."""

    file_path: str
    changed: bool
    content: Optional[str] = None  # New content if changed
    diagnostics: List[Diagnostic] = field(default_factory=list)

    def has_unsafe(self) -> bool:
        """Return True if any diagnostic has ERROR severity."""
        return any(d.severity == DiagnosticSeverity.ERROR for d in self.diagnostics)


# ============================================================================
# Transformation specifications
# ============================================================================

@dataclass
class StructuredTransformation:
    """Specifies a single structured reference transformation."""

    # What to match: format (toml/json/yaml) and key path (dot-separated)
    file_format: str  # "toml", "json", "yaml"
    key_path: str     # e.g., "project.name" or "["scripts"]["key"]"

    # What to replace
    old_value: str    # The old identity/reference value
    new_value: str    # The new identity/reference value

    # Transformation behavior flags
    match_type: str = "exact"  # "exact" = exact string match, "prefix" = starts-with
    recursive: bool = False    # Search all nested keys if True


# ============================================================================
# TOML transformation
# ============================================================================

def _transform_toml(
    content: str,
    transformations: List[StructuredTransformation],
    file_path: str,
) -> TransformationResult:
    """Transform TOML content using tomli/tomli_w for round-trip preservation."""

    if tomli is None or tomli_w is None:
        return TransformationResult(
            file_path=file_path,
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message="tomli/tomli_w not installed; cannot parse TOML",
                    file_path=file_path,
                )
            ],
        )

    try:
        data = tomli.loads(content)
    except Exception as e:
        return TransformationResult(
            file_path=file_path,
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message=f"TOML parse error: {e}",
                    file_path=file_path,
                )
            ],
        )

    changed = False
    diagnostics: List[Diagnostic] = []

    # Apply TOML-specific transformations
    for trans in transformations:
        if trans.file_format != "toml":
            continue

        # Parse dot-separated key path
        keys = trans.key_path.split(".")
        current = data

        # Navigate to parent of target key
        for key in keys[:-1]:
            if isinstance(current, dict) and key in current:
                current = current[key]
            else:
                break
        else:
            # Successfully navigated to parent
            final_key = keys[-1]
            if isinstance(current, dict) and final_key in current:
                old_val = current[final_key]
                if isinstance(old_val, str) and old_val == trans.old_value:
                    current[final_key] = trans.new_value
                    changed = True
                    diagnostics.append(
                        Diagnostic(
                            kind=DiagnosticKind.TOML_KEY_REWRITTEN,
                            severity=DiagnosticSeverity.INFO,
                            message=f'TOML key "{trans.key_path}" rewritten: '
                                   f'"{trans.old_value}" → "{trans.new_value}"',
                            file_path=file_path,
                        )
                    )

    if changed:
        try:
            new_content = tomli_w.dumps(data)
            return TransformationResult(
                file_path=file_path,
                changed=True,
                content=new_content,
                diagnostics=diagnostics,
            )
        except Exception as e:
            return TransformationResult(
                file_path=file_path,
                changed=False,
                diagnostics=[
                    Diagnostic(
                        kind=DiagnosticKind.UNSAFE_TOML_CONSTRUCT,
                        severity=DiagnosticSeverity.ERROR,
                        message=f"TOML serialization failed: {e}",
                        file_path=file_path,
                    )
                ],
            )

    return TransformationResult(
        file_path=file_path,
        changed=False,
        diagnostics=diagnostics,
    )


# ============================================================================
# JSON transformation
# ============================================================================

def _transform_json(
    content: str,
    transformations: List[StructuredTransformation],
    file_path: str,
) -> TransformationResult:
    """Transform JSON content while preserving structure."""

    try:
        data = json.loads(content)
    except Exception as e:
        return TransformationResult(
            file_path=file_path,
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message=f"JSON parse error: {e}",
                    file_path=file_path,
                )
            ],
        )

    changed = False
    diagnostics: List[Diagnostic] = []

    # Apply JSON transformations
    for trans in transformations:
        if trans.file_format != "json":
            continue

        # Parse dot-separated key path
        keys = trans.key_path.split(".")
        current = data

        # Navigate to parent of target key
        for key in keys[:-1]:
            if isinstance(current, dict) and key in current:
                current = current[key]
            else:
                break
        else:
            # Successfully navigated to parent
            final_key = keys[-1]
            if isinstance(current, dict) and final_key in current:
                old_val = current[final_key]
                if isinstance(old_val, str) and old_val == trans.old_value:
                    current[final_key] = trans.new_value
                    changed = True
                    diagnostics.append(
                        Diagnostic(
                            kind=DiagnosticKind.JSON_KEY_REWRITTEN,
                            severity=DiagnosticSeverity.INFO,
                            message=f'JSON key "{trans.key_path}" rewritten: '
                                   f'"{trans.old_value}" → "{trans.new_value}"',
                            file_path=file_path,
                        )
                    )

    if changed:
        try:
            new_content = json.dumps(data, indent=2)
            return TransformationResult(
                file_path=file_path,
                changed=True,
                content=new_content,
                diagnostics=diagnostics,
            )
        except Exception as e:
            return TransformationResult(
                file_path=file_path,
                changed=False,
                diagnostics=[
                    Diagnostic(
                        kind=DiagnosticKind.UNSAFE_JSON_CONSTRUCT,
                        severity=DiagnosticSeverity.ERROR,
                        message=f"JSON serialization failed: {e}",
                        file_path=file_path,
                    )
                ],
            )

    return TransformationResult(
        file_path=file_path,
        changed=False,
        diagnostics=diagnostics,
    )


# ============================================================================
# YAML transformation
# ============================================================================

def _transform_yaml(
    content: str,
    transformations: List[StructuredTransformation],
    file_path: str,
) -> TransformationResult:
    """Transform YAML content using PyYAML while preserving comments/formatting."""

    if yaml is None:
        return TransformationResult(
            file_path=file_path,
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message="PyYAML not installed; cannot parse YAML",
                    file_path=file_path,
                )
            ],
        )

    try:
        # Use safe_load for security; comments will be lost
        data = yaml.safe_load(content)
    except Exception as e:
        return TransformationResult(
            file_path=file_path,
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message=f"YAML parse error: {e}",
                    file_path=file_path,
                )
            ],
        )

    changed = False
    diagnostics: List[Diagnostic] = []

    # Apply YAML transformations
    for trans in transformations:
        if trans.file_format != "yaml":
            continue

        # Parse dot-separated key path
        keys = trans.key_path.split(".")
        current = data

        # Navigate to parent of target key
        for key in keys[:-1]:
            if isinstance(current, dict) and key in current:
                current = current[key]
            else:
                break
        else:
            # Successfully navigated to parent
            final_key = keys[-1]
            if isinstance(current, dict) and final_key in current:
                old_val = current[final_key]
                if isinstance(old_val, str) and old_val == trans.old_value:
                    current[final_key] = trans.new_value
                    changed = True
                    diagnostics.append(
                        Diagnostic(
                            kind=DiagnosticKind.YAML_KEY_REWRITTEN,
                            severity=DiagnosticSeverity.INFO,
                            message=f'YAML key "{trans.key_path}" rewritten: '
                                   f'"{trans.old_value}" → "{trans.new_value}"',
                            file_path=file_path,
                        )
                    )

    if changed:
        try:
            new_content = yaml.dump(data, default_flow_style=False, sort_keys=False)
            return TransformationResult(
                file_path=file_path,
                changed=True,
                content=new_content,
                diagnostics=diagnostics,
            )
        except Exception as e:
            return TransformationResult(
                file_path=file_path,
                changed=False,
                diagnostics=[
                    Diagnostic(
                        kind=DiagnosticKind.UNSAFE_YAML_CONSTRUCT,
                        severity=DiagnosticSeverity.ERROR,
                        message=f"YAML serialization failed: {e}",
                        file_path=file_path,
                    )
                ],
            )

    return TransformationResult(
        file_path=file_path,
        changed=False,
        diagnostics=diagnostics,
    )


# ============================================================================
# Public API
# ============================================================================

def transform_file(
    file_path: Path,
    transformations: List[StructuredTransformation],
    file_format: Optional[str] = None,
) -> TransformationResult:
    """
    Transform a single structured file.

    Args:
        file_path: Path to the file to transform
        transformations: List of transformations to apply
        file_format: File format ("toml", "json", "yaml"). If None, inferred from extension.

    Returns:
        TransformationResult with changes and diagnostics
    """

    if not file_path.exists():
        return TransformationResult(
            file_path=str(file_path),
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message=f"File not found: {file_path}",
                    file_path=str(file_path),
                )
            ],
        )

    # Infer format from extension if not provided
    if file_format is None:
        suffix = file_path.suffix.lower()
        if suffix == ".toml":
            file_format = "toml"
        elif suffix == ".json":
            file_format = "json"
        elif suffix in (".yaml", ".yml"):
            file_format = "yaml"
        else:
            return TransformationResult(
                file_path=str(file_path),
                changed=False,
                diagnostics=[
                    Diagnostic(
                        kind=DiagnosticKind.PARSE_ERROR,
                        severity=DiagnosticSeverity.ERROR,
                        message=f"Unknown file format: {file_path.suffix}",
                        file_path=str(file_path),
                    )
                ],
            )

    try:
        content = file_path.read_text(encoding="utf-8")
    except Exception as e:
        return TransformationResult(
            file_path=str(file_path),
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message=f"Failed to read file: {e}",
                    file_path=str(file_path),
                )
            ],
        )

    # Route to format-specific transformer
    if file_format == "toml":
        return _transform_toml(content, transformations, str(file_path))
    elif file_format == "json":
        return _transform_json(content, transformations, str(file_path))
    elif file_format == "yaml":
        return _transform_yaml(content, transformations, str(file_path))
    else:
        return TransformationResult(
            file_path=str(file_path),
            changed=False,
            diagnostics=[
                Diagnostic(
                    kind=DiagnosticKind.PARSE_ERROR,
                    severity=DiagnosticSeverity.ERROR,
                    message=f"Unsupported format: {file_format}",
                    file_path=str(file_path),
                )
            ],
        )


def transform_files_dry_run(
    file_paths: List[Path],
    transformations: List[StructuredTransformation],
) -> List[TransformationResult]:
    """
    Run dry-run transformations on multiple files (read-only).

    Args:
        file_paths: Paths to files to transform
        transformations: Transformations to apply

    Returns:
        List of TransformationResults
    """
    results = []
    for file_path in file_paths:
        result = transform_file(file_path, transformations)
        results.append(result)
    return results


